"""Luhn algorithm card number validation."""


def valid(number: str) -> bool:
    """Return whether *number* passes the Luhn check.

    Spaces are ignored. The input is invalid if it contains fewer than two
    digits or any character other than an ASCII digit (after removing spaces).
    """
    if not isinstance(number, str):
        return False

    digits = number.replace(' ', '')
    if len(digits) < 2 or any(char < '0' or char > '9' for char in digits):
        return False

    total = 0
    for index, char in enumerate(reversed(digits)):
        digit = ord(char) - ord('0')
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
